/** how far out of order a position may arrive and still be trusted. */
const SKEW_MS = 90 * 1000;

/**
 * folds one position into a vehicle's zone membership.
 *
 * a position older than the one already recorded is dropped rather than
 * applied: applying it would move the vehicle backwards through a boundary
 * it never crossed, and every such move is an alert somebody is woken by.
 * @param state the membership as last known
 * @param fix the position that just arrived
 * @returns the new membership, and any transition it caused
 */
export function fold(state: Membership, fix: Fix): Folded {
  if (fix.at <= state.at) return { state, transition: undefined };
  if (fix.at - state.at > SKEW_MS && !fix.trusted)
    return { state, transition: undefined };

  const inside = zonesContaining(fix.point);
  const entered = inside.filter((zone) => !state.inside.has(zone));
  const left = [...state.inside].filter((zone) => !inside.includes(zone));

  return {
    state: { at: fix.at, inside: new Set(inside) },
    transition: entered.length || left.length ? { entered, left } : undefined,
  };
}
